<?php
require_once __DIR__.'/../config/database.php';$pdo=db();$dir=__DIR__.'/../uploads/nonceblox';if(!is_dir($dir))mkdir($dir,0770,true);$rows=$pdo->query("SELECT id,COALESCE(NULLIF(source_url,''),stored_file) url FROM candidates WHERE source_name='NonceBlox website'")->fetchAll();$update=$pdo->prepare('UPDATE candidates SET source_url=?,stored_file=? WHERE id=?');$ok=0;$failed=0;$skipped=0;
foreach($rows as $row){$url=trim((string)$row['url']);if(!filter_var($url,FILTER_VALIDATE_URL)){$failed++;continue;}$path=parse_url($url,PHP_URL_PATH);$ext=strtolower(pathinfo((string)$path,PATHINFO_EXTENSION));if(!in_array($ext,['pdf','doc','docx'],true)){$failed++;continue;}$target=$dir.'/'.$row['id'].'.'.$ext;if(is_file($target)&&filesize($target)>100){$update->execute([$url,'nonceblox/'.$row['id'].'.'.$ext,$row['id']]);$skipped++;continue;}$fh=fopen($target,'wb');$ch=curl_init($url);curl_setopt_array($ch,[CURLOPT_FILE=>$fh,CURLOPT_FOLLOWLOCATION=>true,CURLOPT_MAXREDIRS=>3,CURLOPT_CONNECTTIMEOUT=>8,CURLOPT_TIMEOUT=>30,CURLOPT_USERAGENT=>'ResumeIQ/1.0',CURLOPT_PROTOCOLS=>CURLPROTO_HTTP|CURLPROTO_HTTPS]);$success=curl_exec($ch);$status=(int)curl_getinfo($ch,CURLINFO_RESPONSE_CODE);$type=(string)curl_getinfo($ch,CURLINFO_CONTENT_TYPE);curl_close($ch);fclose($fh);$size=is_file($target)?filesize($target):0;if(!$success||$status<200||$status>=300||$size<100||str_contains(strtolower($type),'text/html')){if(is_file($target))unlink($target);$failed++;continue;}$update->execute([$url,'nonceblox/'.$row['id'].'.'.$ext,$row['id']]);$ok++;}
echo "downloaded=$ok\nskipped=$skipped\nfailed=$failed\ntotal=".count($rows)."\n";
